class AppException extends Exception {
    AppException(String message) {
        super(message);
    }
}
public class Main {
    static void work(int n) throws AppException {
        if (n < 0) throw new AppException("bad");
        System.out.print("W");
    }
    public static void main(String[] args) {
        try {
            work(-1);
            System.out.print("A");
        } catch (AppException e) {
            System.out.print(e.getMessage());
        }
    }
}

class MyRuntimeException extends RuntimeException { }
public class Main {
    static void work(boolean fail) {
        if (fail) throw new MyRuntimeException();
        System.out.print("W");
    }
    public static void main(String[] args) {
        try {
            work(true);
            System.out.print("A");
        } catch (RuntimeException e) {
            System.out.print("R");
        }
    }
}

